-- ============================================================================
-- OGFZA Mono Payments - Demo seed data
-- Run this in the Supabase SQL editor after the schema migration.
-- Safe to re-run: it clears its own rows first (by known UUID prefix).
-- ============================================================================

delete from payments where member_id in (select id from members where ogfza_member_id like 'OGFZACOOP0%');
delete from payment_schedules where member_id in (select id from members where ogfza_member_id like 'OGFZACOOP0%');
delete from mandates where member_id in (select id from members where ogfza_member_id like 'OGFZACOOP0%');
delete from reconciliation where period in ('2026-08-01', '2026-09-01');
delete from members where ogfza_member_id like 'OGFZACOOP0%';

